={{ { query: `query DatosSeguimiento($inicioDia: timestamptz!) {
  solicitudes_cotizacion(where: { estado: { _eq: "inicio" }, preparada_para_envio: { _eq: true } }) {
    id codigo nombre creado_por fecha_limite frecuencia_aviso_dias partida_critica
  }
  solicitud_proveedores(where: { solicitud_cotizacion: { estado: { _eq: "inicio" } } }) {
    solicitud_id proveedor_id estado_respuesta detalle_respuesta considerado numero_coordinaciones
    proveedor_asociado { nombre correo }
  }
  envios_solicitud(where: { estado: { _eq: "enviado" } }) {
    solicitud_id proveedor_id enviado_at
  }
  notificaciones(where: { created_at: { _gte: $inicioDia } }) { dedupe_key }
}`, variables: { inicioDia: $now.setZone('America/Lima').startOf('day').toISO() } } }}

parameters.jsCode:
const datos = $json.data;
if (!datos) throw new Error('Nhost no devolvió datos para el seguimiento.');
const hoy = $now.setZone('America/Lima').toISODate();
const solicitudes = new Map((datos.solicitudes_cotizacion ?? []).map((item) => [item.id, item]));
const envios = new Map((datos.envios_solicitud ?? []).map((item) => [`${item.solicitud_id}:${item.proveedor_id}`, item.enviado_at]));
const existentes = new Set((datos.notificaciones ?? []).map((item) => item.dedupe_key));
const grupos = new Map();
for (const participacion of datos.solicitud_proveedores ?? []) {
  if (!solicitudes.has(participacion.solicitud_id)) continue;
  if (!grupos.has(participacion.solicitud_id)) grupos.set(participacion.solicitud_id, []);
  grupos.get(participacion.solicitud_id).push(participacion);
}
const fechaLima = (valor) => /^\d{4}-\d{2}-\d{2}$/.test(String(valor))
  ? String(valor)
  : new Date(valor).toLocaleDateString('en-CA', { timeZone: 'America/Lima' });
const fechaDia = (valor) => Date.parse(`${fechaLima(valor)}T12:00:00Z`);
const etiquetas = {
  no_envio_cotizacion: 'Respuesta sin nueva cotización ni ficha técnica',
  envio_cotizacion_con_aclaracion: 'Cotización o ficha técnica recibida',
  envio_cotizacion: 'Cotización o ficha técnica aceptada como final',
};
const items = [];
for (const [solicitudId, participantes] of grupos) {
  const solicitud = solicitudes.get(solicitudId);
  const excluidos = [];
  const estados = [];
  let corresponde = false;
  for (const participacion of participantes) {
    const envio = envios.get(`${solicitudId}:${participacion.proveedor_id}`);
    if (!envio) continue;
    const diasProveedor = Math.floor((fechaDia(hoy) - fechaDia(envio)) / 86400000);
    if (diasProveedor >= solicitud.frecuencia_aviso_dias
        && diasProveedor % solicitud.frecuencia_aviso_dias === 0) corresponde = true;
    const sinCotizacion = participacion.estado_respuesta === 'no_envio_cotizacion';
    const excluir = participacion.considerado && sinCotizacion && (
      participacion.numero_coordinaciones >= 3 || solicitud.fecha_limite < hoy
    );
    if (excluir) excluidos.push(participacion.proveedor_id);
    estados.push({
      proveedor: participacion.proveedor_asociado.nombre,
      correo: participacion.proveedor_asociado.correo,
      estado: excluir ? 'No envió cotización ni ficha técnica' : etiquetas[participacion.estado_respuesta],
      coordinaciones: participacion.numero_coordinaciones,
      considerado: excluir ? false : participacion.considerado,
    });
  }
  if (!estados.length) continue;
  if (!corresponde && !excluidos.length) continue;
  const clave = `seguimiento:${solicitudId}:${hoy}`;
  if (existentes.has(clave)) continue;
  const resumen = estados.map((item) => `${item.proveedor}: ${item.estado}`).join(' · ');
  items.push({ json: {
    solicitudId,
    excluidos,
    notificacion: {
      usuario_id: solicitud.creado_por,
      solicitud_id: solicitudId,
      tipo: 'resumen_seguimiento',
      titulo: `Seguimiento ${solicitud.codigo} — ${solicitud.nombre}`,
      mensaje: resumen,
      datos: { fecha: hoy, partida_critica: solicitud.partida_critica, proveedores: estados },
      dedupe_key: clave,
    },
  }});
}
return items;

