={{ { query: `mutation RegistrarSeguimiento($solicitudId: uuid!, $excluidos: [uuid!]!, $notificacion: notificaciones_insert_input!) {
  update_solicitud_proveedores(
    where: { solicitud_id: { _eq: $solicitudId }, proveedor_id: { _in: $excluidos } }
    _set: {
      estado_respuesta: "no_envio_cotizacion"
      detalle_respuesta: "plazo_vencido"
      considerado: false
      origen_clasificacion: "sistema"
    }
  ) { affected_rows }
  insert_notificaciones_one(
    object: $notificacion
    on_conflict: { constraint: notificaciones_dedupe_key_key, update_columns: [] }
  ) { id }
}`, variables: { solicitudId: $json.solicitudId, excluidos: $json.excluidos, notificacion: $json.notificacion } } }}
